// Authenticate the request before anything downstream touches the payload.
//
// The webhook URL is effectively public, so a request that arrives here has
// proved nothing yet. There are two ways it can prove something, because the
// two places this workflow runs do not offer the same tools:
//
//   HMAC signature   The strong one. Covers the exact bytes sent and carries a
//                    timestamp, so a captured request cannot be replayed. Needs
//                    the shared secret, which a Code node can only reach through
//                    $env (self-hosted) or $vars (n8n Cloud, paid plans).
//
//   Header Auth      The fallback for n8n Cloud on a free plan, where neither of
//                    those is available. The token lives in a credential, which
//                    is the only store a Code node cannot read -- so the Webhook
//                    node checks it, before this code runs, and by the time we
//                    are here the request is already authenticated.
//
// If neither is available this throws rather than passing the payload through.
// A verifier that waves requests along when it cannot verify them is worse than
// no verifier, because it looks like one.

const crypto = require('crypto');

const TOLERANCE_SECONDS = 300;

function readSecret() {
  try {
    if (typeof $vars !== 'undefined' && $vars.CONSERJE_WEBHOOK_SECRET) {
      return $vars.CONSERJE_WEBHOOK_SECRET;
    }
  } catch (e) {
    // $vars is not available on this instance; fall through to $env.
  }

  try {
    return $env.CONSERJE_WEBHOOK_SECRET;
  } catch (e) {
    return undefined;
  }
}

const item = $input.first();
const headers = item.json.headers || {};

if (!item.binary || !item.binary.data) {
  throw new Error(
    'Rejected: no raw body. Enable "Raw Body" in the webhook node options.'
  );
}

const raw = Buffer.from(item.binary.data.data, 'base64').toString('utf8');
const secret = readSecret();

if (secret) {
  const signature = headers['x-conserje-signature'];
  const timestamp = Number(headers['x-conserje-timestamp']);

  if (!signature || !Number.isFinite(timestamp)) {
    throw new Error('Rejected: signature headers are missing.');
  }

  // Reject stale requests: without this, a captured payload stays replayable
  // forever, because its signature never stops being correct.
  const now = Math.floor(Date.now() / 1000);

  if (Math.abs(now - timestamp) > TOLERANCE_SECONDS) {
    throw new Error('Rejected: timestamp outside tolerance, possible replay.');
  }

  const expected = crypto
    .createHmac('sha256', secret)
    .update(`${timestamp}.${raw}`)
    .digest('hex');

  const expectedBuffer = Buffer.from(expected, 'utf8');
  const actualBuffer = Buffer.from(String(signature), 'utf8');

  // Length is checked first because timingSafeEqual throws on a mismatch.
  if (
    expectedBuffer.length !== actualBuffer.length ||
    !crypto.timingSafeEqual(expectedBuffer, actualBuffer)
  ) {
    throw new Error('Rejected: bad signature.');
  }
} else if (!headers['x-conserje-token']) {
  // No secret to verify with, and the request did not even carry the token the
  // Webhook node's Header Auth would have checked -- so nothing authenticated
  // this request and nothing here can.
  throw new Error(
    'Rejected: no CONSERJE_WEBHOOK_SECRET readable and no token header present. ' +
    'Self-hosted: set the secret in n8n/.env. ' +
    'n8n Cloud: enable Header Auth on the webhook node with the "Conserje webhook token" credential.'
  );
}

return [{ json: JSON.parse(raw) }];

